Here's a MATLAB program to convert ultrasound signal from voltage vs time to magnitude (dB) vs frequency (MHz):

```matlab
function [freq_MHz, magnitude_dB] = ultrasound_fft_conversion(time, voltage, varargin)
% ULTRASOUND_FFT_CONVERSION Converts ultrasound signal from time to frequency domain
%
% Inputs:
%   time     - Time vector in seconds
%   voltage  - Voltage signal vector
%   varargin - Optional parameters:
%              'WindowType' - Window function ('hann', 'hamming', 'blackman', 'rect')
%              'Padding'    - Zero padding factor (default: 1, no padding)
%              'RefVoltage' - Reference voltage for dB calculation (default: 1)
%
% Outputs:
%   freq_MHz     - Frequency vector in MHz
%   magnitude_dB - Magnitude spectrum in dB

    % Parse optional inputs
    p = inputParser;
    addParameter(p, 'WindowType', 'hann', @ischar);
    addParameter(p, 'Padding', 1, @isnumeric);
    addParameter(p, 'RefVoltage', 1, @isnumeric);
    parse(p, varargin{:});

    window_type = p.Results.WindowType;
    padding_factor = p.Results.Padding;
    ref_voltage = p.Results.RefVoltage;

    % Ensure column vectors
    time = time(:);
    voltage = voltage(:);

    % Calculate sampling parameters
    N = length(voltage);
    dt = mean(diff(time));  % Sampling interval
    fs = 1/dt;              % Sampling frequency in Hz

    % Apply window function
    switch lower(window_type)
        case 'hann'
            window = hann(N);
        case 'hamming'
            window = hamming(N);
        case 'blackman'
            window = blackman(N);
        case 'rect'
            window = ones(N, 1);
        otherwise
            window = hann(N);
    end

    voltage_windowed = voltage .* window;

    % Apply zero padding if requested
    N_padded = round(N * padding_factor);
    if N_padded > N
        voltage_windowed = [voltage_windowed; zeros(N_padded - N, 1)];
    end

    % Perform FFT
    Y = fft(voltage_windowed);

    % Calculate single-sided spectrum
    if mod(N_padded, 2) == 0
        % Even number of samples
        Y_single = Y(1:N_padded/2+1);
        Y_single(2:end-1) = 2*Y_single(2:end-1);
    else
        % Odd number of samples
        Y_single = Y(1:(N_padded+1)/2);
        Y_single(2:end) = 2*Y_single(2:end);
    end

    % Calculate magnitude spectrum
    magnitude = abs(Y_single)/N;

    % Convert to dB (20*log10 for voltage)
    magnitude_dB = 20*log10(magnitude/ref_voltage);

    % Create frequency vector in MHz
    freq_Hz = (0:length(Y_single)-1)' * (fs/N_padded);
    freq_MHz = freq_Hz / 1e6;

    % Plot if no output arguments
    if nargout == 0
        figure;

        % Plot time domain signal
        subplot(2,1,1);
        plot(time*1e6, voltage);
        xlabel('Time (\mus)');
        ylabel('Voltage (V)');
        title('Ultrasound Signal - Time Domain');
        grid on;

        % Plot frequency domain signal
        subplot(2,1,2);
        plot(freq_MHz, magnitude_dB);
        xlabel('Frequency (MHz)');
        ylabel('Magnitude (dB)');
        title('Ultrasound Signal - Frequency Domain');
        grid on;
        xlim([0 max(freq_MHz)/2]); % Show up to Nyquist frequency
    end
end
```

Here's an example script showing how to use the function:

```matlab
%% Example Usage Script
clear; clc; close all;

% Generate synthetic ultrasound signal for demonstration
fs = 100e6;  % 100 MHz sampling frequency
t = 0:1/fs:100e-6;  % 100 microseconds of data

% Create a multi-frequency ultrasound signal
f1 = 2.5e6;   % 2.5 MHz
f2 = 5e6;     % 5 MHz
f3 = 7.5e6;   % 7.5 MHz

% Generate signal with multiple frequency components
signal = 0.5*sin(2*pi*f1*t) + 0.3*sin(2*pi*f2*t) + 0.2*sin(2*pi*f3*t);

% Add some noise
signal = signal + 0.05*randn(size(t));

% Add exponential decay (typical for ultrasound)
signal = signal .* exp(-t/50e-6);

%% Method 1: Use the function with default parameters
[freq_MHz, mag_dB] = ultrasound_fft_conversion(t, signal);

%% Method 2: Use the function with custom parameters
[freq_MHz2, mag_dB2] = ultrasound_fft_conversion(t, signal, ...
    'WindowType', 'blackman', ...
    'Padding', 4, ...
    'RefVoltage', 1);

%% Plot comparison
figure;

% Original signal
subplot(3,1,1);
plot(t*1e6, signal);
xlabel('Time (\mus)');
ylabel('Voltage (V)');
title('Original Ultrasound Signal');
grid on;

% FFT without padding
subplot(3,1,2);
plot(freq_MHz, mag_dB);
xlabel('Frequency (MHz)');
ylabel('Magnitude (dB)');
title('FFT - Hann Window, No Padding');
grid on;
xlim([0 20]);
ylim([-80 0]);

% FFT with padding
subplot(3,1,3);
plot(freq_MHz2, mag_dB2);
xlabel('Frequency (MHz)');
ylabel('Magnitude (dB)');
title('FFT - Blackman Window, 4x Padding');
grid on;
xlim([0 20]);
ylim([-80 0]);

%% Alternative: Simple inline conversion
% If you prefer a simpler approach without the function:

% Parameters
N = length(signal);
dt = t(2) - t(1);
fs = 1/dt;

% Apply window
window = hann(N)';
signal_windowed = signal .* window;

% FFT
Y = fft(signal_windowed);
Y_single = Y(1:N/2+1);
Y_single(2:end-1) = 2*Y_single(2:end-1);

% Magnitude in dB
magnitude = abs(Y_single)/N;
magnitude_dB = 20*log10(magnitude);

% Frequency vector in MHz
freq = (0:N/2) * (fs/N) / 1e6;

% Plot
figure;
plot(freq, magnitude_dB);
xlabel('Frequency (MHz)');
ylabel('Magnitude (dB)');
title('Simple FFT Conversion');
grid on;
xlim([0 20]);
```

Key features of this program:

1. **Window Functions**: Applies window functions (Hann, Hamming, Blackman) to reduce spectral leakage
2. **Zero Padding**: Optional zero padding for increased frequency resolution
3. **dB Conversion**: Converts voltage magnitude to dB (20*log10 for voltage ratios)
4. **Single-sided Spectrum**: Shows only positive frequencies relevant for real signals
5. **Flexible Input**: Accepts various optional parameters
6. **Automatic Plotting**: Plots results if no output arguments are specified

The program handles the conversion properly by:
- Calculating the sampling frequency from the time vector
- Applying appropriate windowing to reduce spectral artifacts
- Computing the FFT and extracting the magnitude spectrum
- Converting to dB scale relative to a reference voltage
- Converting frequency axis from Hz to MHz for ultrasound applications

